class Command:
    def execute(self):
        pass

    def undo(self):
        pass


class AddTextCommand(Command):
    def __init__(self, editor, text):
        self.editor = editor
        self.text = text
        self.prev_content = ""

    def execute(self):
        self.prev_content = self.editor.content
        self.editor.content += self.text

    def undo(self):
        self.editor.content = self.prev_content


class DeleteLineCommand(Command):
    def __init__(self, editor):
        self.editor = editor
        self.deleted_line = ""

    def execute(self):
        if "\n" in self.editor.content:
            lines = self.editor.content.split("\n")
            self.deleted_line = lines[-1]
            self.editor.content = "\n".join(lines[:-1])
        else:
            self.deleted_line = self.editor.content
            self.editor.content = ""

    def undo(self):
        if self.editor.content:
            self.editor.content += "\n" + self.deleted_line
        else:
            self.editor.content = self.deleted_line


class ReplaceCommand(Command):
    def __init__(self, editor, old, new):
        self.editor = editor
        self.old = old
        self.new = new
        self.prev_content = ""

    def execute(self):
        self.prev_content = self.editor.content
        self.editor.content = self.editor.content.replace(self.old, self.new)

    def undo(self):
        self.editor.content = self.prev_content


class Editor:
    def __init__(self):
        self.content = ""
        self.history = []
        self.redo_stack = []

    def execute(self, command):
        command.execute()
        self.history.append(command)
        self.redo_stack.clear()

    def undo(self):
        if self.history:
            command = self.history.pop()
            command.undo()
            self.redo_stack.append(command)

    def redo(self):
        if self.redo_stack:
            command = self.redo_stack.pop()
            command.execute()
            self.history.append(command)

    def show(self):
        print(f"Content: '{self.content}'")


