    entries = []
    with open(filepath) as f:
        for line in f:
            entry = parse_log_line(line)
            if entry:
                entries.append(entry)
    errors = filter_by_level(entries, "ERROR")
    warnings = filter_by_level(entries, "WARN")
    by_hour = group_by_hour(entries)
