class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
        self.word_count = 0


class Trie:
    def __init__(self):
        self.root = TrieNode()
        self.total_words = 0

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        if not node.is_end:
            node.is_end = True
            self.total_words += 1
        node.word_count += 1

    def search(self, word):
        node = self._find_node(word)
        return node is not None and node.is_end

    def starts_with(self, prefix):
        return self._find_node(prefix) is not None

    def _find_node(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

    def autocomplete(self, prefix, limit=10):
        node = self._find_node(prefix)
        if node is None:
            return []
        results = []
        self._dfs(node, prefix, results, limit)
        return results

    def _dfs(self, node, prefix, results, limit):
        if len(results) >= limit:
            return
        if node.is_end:
            results.append(prefix)
        for char in sorted(node.children.keys()):
            self._dfs(node.children[char], prefix + char, results, limit)

    def remove(self, word):
        return self._remove(self.root, word, 0)

    def _remove(self, node, word, depth):
        if depth == len(word):
            if not node.is_end:
                return False
            node.is_end = False
            self.total_words -= 1
            return len(node.children) == 0
        char = word[depth]
        if char not in node.children:
            return False
        should_delete = self._remove(node.children[char], word, depth + 1)
        if should_delete:
            del node.children[char]
            return len(node.children) == 0 and not node.is_end
        return False


