class Snake:
    def __init__(self, width=20, height=20):
        self.width = width
        self.height = height
        self.body = [(height // 2, width // 2)]
        self.direction = (0, 1)
        self.food = self._spawn_food()
        self.score = 0
        self.game_over = False

    def _spawn_food(self):
        while True:
            pos = (random.randint(0, self.height - 1), random.randint(0, self.width - 1))
            if pos not in self.body:
                return pos

    def set_direction(self, dx, dy):
        if (dx, dy) != (-self.direction[0], -self.direction[1]):
            self.direction = (dx, dy)

    def step(self):
        if self.game_over:
            return
        head = self.body[0]
        new_head = (head[0] + self.direction[0], head[1] + self.direction[1])
        if (new_head[0] < 0 or new_head[0] >= self.height or
                new_head[1] < 0 or new_head[1] >= self.width or
                new_head in self.body):
            self.game_over = True
            return
        self.body.insert(0, new_head)
        if new_head == self.food:
            self.score += 10
            self.food = self._spawn_food()
        else:
            self.body.pop()

    def render(self):
        grid = [["." for _ in range(self.width)] for _ in range(self.height)]
        for r, c in self.body:
            grid[r][c] = "O"
        grid[self.food[0]][self.food[1]] = "*"
        for row in grid:
            print("".join(row))
        print(f"Score: {self.score}")


