import random

class Character:
    def __init__(self, name, hp, attack, defense):
        self.name = name
        self.hp = hp
        self.max_hp = hp
        self.attack = attack
        self.defense = defense
        self.effects = []

    def is_alive(self):
        return self.hp > 0

    def take_damage(self, amount):
        actual = max(1, amount - self.defense)
        self.hp -= actual
        return actual

    def heal(self, amount):
        self.hp = min(self.max_hp, self.hp + amount)
        return amount

    def apply_effects(self):
        expired = []
        for i, (effect, duration, value) in enumerate(self.effects):
            if effect == "poison":
                self.hp -= value
            elif effect == "regen":
                self.hp = min(self.max_hp, self.hp + value)
            self.effects[i] = (effect, duration - 1, value)
            if duration - 1 <= 0:
                expired.append(i)
        for i in reversed(expired):
            self.effects.pop(i)

    def add_effect(self, effect, duration, value):
        self.effects.append((effect, duration, value))

    def status(self):
        return f"{self.name}: HP={self.hp}/{self.max_hp} ATK={self.attack} DEF={self.defense}"


