    def is_over(self):
        return not self.player.is_alive() or not self.enemy.is_alive()

    def next_turn(self):
        self.player.apply_effects()
        self.enemy.apply_effects()
        self.turn += 1

    def show_log(self):
        for entry in self.log:
            print(entry)
        print(f"
{self.player.status()}")
        print(f"{self.enemy.status()}")


