print(f"p1 + p2 = {p1.add(p2)}")
print(f"p1 * p2 = {p1.multiply(p2)}")
print(f"p1(2) = {p1.evaluate(2)}")
print(f"p1' = {p1.derivative()}")
print(f"p2' = {p2.derivative()}")
print(f"p1 integral = {p1.integral()}")
